/bin/zsh -lc "python3 -B - <<'PY'
from pathlib import Path
import hashlib,json,stat
root=Path.cwd()
files={}
for p in sorted(root.rglob('*')):
    st=p.lstat()
    rel=p.relative_to(root).as_posix()
    if stat.S_ISLNK(st.st_mode):
        raise SystemExit('Symlink not permitted: '+rel)
    if stat.S_ISREG(st.st_mode):
        data=p.read_bytes()
        files[rel]={'sha256':hashlib.sha256(data).hexdigest(),'size':len(data),'mode':stat.S_IMODE(st.st_mode)}
    elif not stat.S_ISDIR(st.st_mode):
        raise SystemExit('Unexpected file type: '+rel)
print(json.dumps({'files':files},sort_keys=True))
PY"

